RateService:
```php
final class RateService
{
    public function __construct(private BillingRepository $repo, private EntityManagerInterface $em, private RateCalculator $calc) {}

    public function rate(): array // [rated:int, unrated:UsageEvent[]]
    {
        $unrated = $this->repo->findUnratedEvents();
        $ratedCount = 0;
        $stillUnrated = [];
        $rowsCache = [];
        foreach ($unrated as $event) {
            $provider = $event->getProvider();
            $model = $event->getModel();
            $cacheKey = $provider->getId().'|'.$model->getCode();
            if (!isset($rowsCache[$cacheKey])) {
                $rowsCache[$cacheKey] = $this->repo->findPriceRowsForModel($provider, $model->getCode());
            }
            $best = null;
            foreach ($rowsCache[$cacheKey] as $row) {
                if ($row->getValidFrom() <= $event->getTs()) {
                    if (null === $best || $row->getValidFrom() > $best->getValidFrom()) {
                        $best = $row;
                    }
                }
            }
            if (null === $best) {
                $stillUnrated[] = $event;
                continue;
            }
            $offPeak = OffPeakWindow::fromProvider($provider);
            $cost = $this->calc->calculate($event, $best, $offPeak);
            $event->markRated($best, $cost->amount());
            $ratedCount++;
        }
        $this->em->flush();
        return [$ratedCount, $stillUnrated];
    }
}
```

