public function testArithmeticIsExactWithoutFloats(): void
{
    // bcmath: 0.1 + 0.2 точно 0.3 (в отличие от float, где 0.30000000000000004)
    self::assertSame('0.300000', DecimalMath::format6(DecimalMath::add('0.1', '0.2')));
